 if(r==='load')return `<div class="formSection"><h3>${tr('Load / cargo specification')}</h3><div class="two">${countryField('pickupCountry','Pickup country')}${countryField('deliveryCountry','Delivery country')}</div><div class="two">${sel('loadType','Load type',['Full truckload','Partial / LTL','Palletised','Refrigerated','Bulk','Hazardous','Oversized','Other'])}${fld('goods','Goods / commodity','text','Food, machinery, retail goods...')}</div><div class="two">${fld('weight','Weight','number','12000')}${sel('weightUnit','Weight unit',['kg','lb','tonnes'])}</div><div class="two">${fld('pallets','Pallets','number','20')}${fld('volume','Volume m³','number','40')}</div>${sel('equipmentNeeded','Equipment needed',['Dry van','Reefer','Flatbed','Tanker','Box truck','Any suitable'])}<div class="two">${fld('tempMin','Minimum temperature °C','number','2')}${fld('tempMax','Maximum temperature °C','number','5')}</div>${fld('pickupDate',available?'Pickup date / time':'Required pickup','datetime-local','')}${fld('details','Cargo notes','text','Non-hazardous, loading requirements...')}</div>${mapWidget('pickup','Pickup location','Exact pickup address or place')}${mapWidget('delivery','Destination','Exact destination address or place')}`;
