async function loadBookings(){if(!me){$('bookingList').innerHTML='';return}const j=await api('/api/bookings');$('bookingList').innerHTML=j.bookings.length?j.bookings.map(b=>{const t=b.trip||{},isBuyer=b.buyerUserId===me.id,isProvider=b.providerUserId===me.id;const checks=[['driverVerified','Driver identity verified'],['licenceVerified','Licence valid for trip'],['truckVerified','Truck / vehicle verified'],['cargoConfirmed','Cargo details confirmed'],['receiverConfirmed','Receiver details confirmed']];return `<article class="card tripCard">
<div class="tripTop"><span class="tag">${esc(b.status||'agreed')}</span><span class="tag">TEST</span></div>
<div class="bookingMoney"><div><small>${tr('Agreement')}</small><strong>${esc(b.currency)} ${esc(b.agreedPrice)}</strong></div><div><small>${tr('TUT Move fee')}</small><strong>${esc(b.platformFeePct)}% · ${esc(b.currency)} ${esc(b.platformFee)}</strong></div><div><small>${tr('Provider net')}</small><strong>${esc(b.currency)} ${esc(b.providerNet)}</strong></div></div>
<div class="testNotice">${tr('TEST MODE — no real money is charged or transferred.')}</div>
${isBuyer&&b.paymentStatus==='test_unpaid'?`<button class="goldBtn mini" onclick="testPay('${b.id}')">${tr('Run test payment')}</button>`:''}
<h4>${tr('Pre-trip verification')}</h4><div class="tripChecks">${checks.map(([k,label])=>`<label><input type="checkbox" id="${k}_${b.id}" ${t[k]?'checked':''}> ${tr(label)}</label>`).join('')}</div>
<label class="readyCheck"><input type="checkbox" id="ready_${b.id}" ${(isBuyer?t.buyerReady:t.providerReady)?'checked':''}> ${tr('I confirm my side is ready for this trip')}</label>
${(isBuyer||isProvider)?`<button class="outlineBtn mini" onclick="saveTripCheck('${b.id}')">${tr('Save trip checks')}</button>`:''}
<div class="tripFlow"><span class="${t.ready?'done':''}">${tr('Verification')}</span><span class="${t.pickupConfirmed?'done':''}">${tr('Pickup')}</span><span class="${b.status==='in_transit'?'done':''}">${tr('In transit')}</span><span class="${b.status==='completed_test'?'done':''}">${tr('Delivered')}</span></div>
${t.ready&&!t.pickupConfirmed?`<button class="goldBtn mini" onclick="confirmPickup('${b.id}')">${tr('Confirm pickup')}</button>`:''}${b.status==='in_transit'?`<button class="goldBtn mini" onclick="confirmDelivery('${b.id}')">${tr('Confirm delivery')}</button>`:''}</article>`}).join(''):`<div class="card">${tr('No agreed bookings yet.')}</div>`}
